import type { DocsScope } from "@/components/docs-mdx/scope";
// Generated by scripts/showcase-data.mjs from the integration registry.
import registryDocsModes from "@/data/docs-modes.json";
import { FRONTENDS, landingPage } from "@/lib/frontends";
import type { FrontendId } from "@/lib/frontends";

// How live docs URLs are scoped, shared by the server resolver
// (`live-docs.ts`) and the client sidebar (`src/proto/live-tree.tsx`).

/** Frameworks with docs but no showcase package, so no manifest. */
export const DOCS_ONLY_FRAMEWORKS = ["a2a", "agent-spec", "deepagents"];

/** The `docs/integrations/<folder>` a framework's own docs live in, when it isn't its slug. */
export const DOCS_FOLDER_OVERRIDES: Record<string, string> = {
  "langgraph-python": "langgraph",
  "langgraph-typescript": "langgraph",
  "langgraph-fastapi": "langgraph",
  "google-adk": "adk",
  "crewai-crews": "crewai-flows",
  strands: "aws-strands",
  "strands-typescript": "aws-strands",
  "ms-agent-dotnet": "microsoft-agent-framework",
  "ms-agent-python": "microsoft-agent-framework",
  "ms-agent-harness-dotnet": "microsoft-agent-framework",
};

/**
 * Each framework with docs, in registry order, and the folder under
 * `docs/integrations` that holds its own pages. A showcase manifest's
 * `docs_mode: hidden` takes a framework out of the docs.
 */
export const LIVE_FRAMEWORKS: Record<string, { folder: string }> =
  Object.fromEntries(
    [
      ...Object.entries(registryDocsModes as Record<string, string>),
      ...DOCS_ONLY_FRAMEWORKS.map((slug) => [slug, "generated"]),
    ].flatMap(([slug, mode]) =>
      mode === "hidden"
        ? []
        : [[slug, { folder: DOCS_FOLDER_OVERRIDES[slug] ?? slug }]],
    ),
  );

/** A framework URL slug's docs, if it has any. */
export function liveFramework(slug: string | undefined) {
  return slug && Object.hasOwn(LIVE_FRAMEWORKS, slug)
    ? LIVE_FRAMEWORKS[slug]
    : undefined;
}

/** The frontend a URL prefix scopes to, if it is one. */
export function liveFrontend(segment: string | undefined) {
  return segment && Object.hasOwn(LIVE_FRONTENDS, segment)
    ? LIVE_FRONTENDS[segment]
    : undefined;
}

/** URL prefixes that scope a page to a frontend (React is the default). */
export const LIVE_FRONTENDS: Record<string, FrontendId> = {
  vue: "vue",
  "react-native": "react-native",
  angular: "angular",
  slack: "slack",
  teams: "teams",
};

/**
 * Where each frontend's own pages live, in lookup order. React's are the
 * pages at the content root; Slack and Teams each have a folder for their
 * connection guide, then share `channels/`. Every frontend with docs also
 * has the shared pages (`docs/(shared)`) and the framework's own; the
 * frontends in early access have none (`landingPage`).
 */
export const FRONTEND_FOLDERS: Partial<Record<FrontendId, string[]>> = {
  react: [],
  vue: ["frontends/vue"],
  angular: ["frontends/angular"],
  "react-native": ["frontends/react-native"],
  slack: ["frontends/slack", "channels"],
  teams: ["frontends/teams", "channels"],
};

/** Slack and Teams are channels with docs: they share the `channels/` guide and a sidebar of their own. */
export function isChannel(frontend: FrontendId) {
  return FRONTEND_FOLDERS[frontend]?.includes("channels") ?? false;
}

/** shell-docs serves the React reference at both `/reference/v2/*` and `/reference/*`. */
export const REFERENCE_ROOT_VERSION = "v2";
/**
 * The reference's own overview (`reference/overview.mdx`), served at
 * `/reference` itself; React's overview stays at `/reference/v2`.
 */
export const REFERENCE_OVERVIEW = "overview";
/** The other SDKs' references live in their own folders under `reference/`. */
export const REFERENCE_FOLDERS = new Set([
  "v1",
  "react-native",
  "vue",
  "angular",
  "core",
  "channels",
]);

/**
 * First URL segments that never take a framework or frontend prefix. An
 * early-access frontend's landing page (`/whatsapp`) is one page for every
 * reader, never `/mastra/whatsapp`.
 */
export const UNSCOPED_SEGMENTS = new Set<string>([
  "docs",
  "ag-ui",
  "reference",
  "frontends",
  "api",
  // Not `agentic-protocols`: its pages are shared ones every stack has
  // (`/vue/mastra/agentic-protocols/mcp`), so its links keep the reader's.
  "cookbook",
  "examples",
  ...FRONTENDS.flatMap((f) => landingPage(f.id)?.slice(1) ?? []),
]);

/** shell-docs' unscoped pages are the built-in agent's docs. */
export const ROOT_FRAMEWORK = "built-in-agent";

/**
 * Keeps a root-relative link in the page's scope, as shell-docs'
 * `resolveDocsHref` does: on `/mastra/...`, `/quickstart` means
 * `/mastra/quickstart`. Links that name a framework or a global section stay
 * as written; a link to a frontend gets the reader's framework. On Slack and Teams, a link into the shared
 * channel guide (`/channels/tools`) opens the reader's own channel's page.
 */
export function scopedHref(href: string | undefined, scope: DocsScope) {
  if (!href?.startsWith("/") || href.startsWith("//")) return href;
  const fe =
    scope.frontend !== "react" ? `/${frontendSegment(scope.frontend)}` : "";
  // shell-docs still serves a framework's pages at their content path
  // (`/docs/integrations/<folder>/...`); here they live at the framework URL.
  const contentPath = href.match(/^\/(?:docs\/)?integrations\/([^/?#]+)(.*)$/);
  if (contentPath) {
    const fw = liveFramework(contentPath[1])
      ? contentPath[1]
      : frameworkForFolder(contentPath[1], scope.framework ?? undefined);
    if (fw) {
      return `${fe}${fw === ROOT_FRAMEWORK ? "" : `/${fw}`}${contentPath[2]}`;
    }
  }
  const channelGuide = href.match(/^\/channels(?=[/?#]|$)(.*)$/);
  if (channelGuide) {
    const channel = isChannel(scope.frontend) ? scope.frontend : "slack";
    return `/${channel}${channelGuide[1]}`;
  }
  const first = href.slice(1).split(/[/?#]/, 1)[0];
  // Content also names a framework by its docs folder (`/langgraph/...`,
  // `/crewai-flows/...`), which shell-docs redirects to a framework URL.
  // Send it to the reader's own framework when that uses the folder.
  const folderFramework = !liveFramework(first)
    ? frameworkForFolder(first, scope.framework ?? undefined)
    : undefined;
  if (folderFramework) {
    return `${fe}/${folderFramework}${href.slice(1 + first.length)}`;
  }
  const fw =
    scope.framework && scope.framework !== ROOT_FRAMEWORK
      ? `/${scope.framework}`
      : "";
  // A link to another frontend (`/vue`) keeps the reader's framework when
  // it names none: from a Google ADK page it opens `/vue/google-adk`.
  if (liveFrontend(first)) {
    const rest = href.slice(1 + first.length);
    const next = rest.split(/[/?#]/, 2)[1];
    return fw && !liveFramework(next) && !UNSCOPED_SEGMENTS.has(next ?? "")
      ? `/${first}${fw}${rest}`
      : href;
  }
  if (!first || UNSCOPED_SEGMENTS.has(first) || liveFramework(first)) {
    return href;
  }
  return `${fe}${fw}${href}`;
}

/**
 * A root-relative link to a per-stack page that names no stack
 * (`/quickstart#install`), as its slug (`quickstart`) and its `?query#hash`.
 * Null for any other link: one that names a framework or frontend, a global
 * section (`/reference`), the channel guide, or an outside URL. A page that
 * isn't per stack (the cookbook) sends these to the reader's own stack.
 */
export function unscopedStackLink(href: string | undefined) {
  if (!href?.startsWith("/") || href.startsWith("//")) return null;
  const path = href.split(/[?#]/, 1)[0];
  const first = path.slice(1).split("/", 1)[0];
  if (
    !first ||
    UNSCOPED_SEGMENTS.has(first) ||
    liveFramework(first) ||
    liveFrontend(first) ||
    first === "channels" ||
    first === "integrations"
  ) {
    return null;
  }
  return {
    slug: path.slice(1).replace(/\/+$/, ""),
    suffix: href.slice(path.length),
  };
}

/** The framework a docs folder name points at: the reader's own if it uses the folder. */
function frameworkForFolder(folder: string, current: string | undefined) {
  if (!folder) return undefined;
  if (current && LIVE_FRAMEWORKS[current]?.folder === folder) return current;
  return Object.entries(LIVE_FRAMEWORKS).find(
    ([, f]) => f.folder === folder,
  )?.[0];
}

/** The URL prefix for a frontend. */
export function frontendSegment(frontend: FrontendId) {
  return (
    Object.entries(LIVE_FRONTENDS).find(([, id]) => id === frontend)?.[0] ??
    frontend
  );
}

/** The frontend and framework a live URL is scoped to. */
export function scopeFromPath(path: string[]): DocsScope & {
  /** The URL's prefix for that scope (`/vue/mastra`). */
  prefix: string;
  /** The page under it (`frontend-tools`). */
  slug: string;
} {
  const frontend = liveFrontend(path[0]);
  const fePrefix = frontend ? `/${path[0]}` : "";
  const framework = frontend ? path[1] : path[0];
  const scoped = (n: number) => path.slice(n).join("/");
  return liveFramework(framework)
    ? {
        frontend: frontend ?? "react",
        framework: framework!,
        prefix: `${fePrefix}/${framework}`,
        slug: scoped(frontend ? 2 : 1),
      }
    : {
        frontend: frontend ?? "react",
        framework: null,
        prefix: fePrefix,
        slug: scoped(frontend ? 1 : 0),
      };
}

/**
 * The URL of `slug` (default: the URL's own page) under another frontend:
 * `/mastra/frontend-tools` on Vue is `/vue/mastra/frontend-tools`. `""` is
 * the frontend's home: its quickstart, or a channel's overview; React's home
 * is the framework's quickstart; an early-access frontend's is its landing
 * page, its only page, whatever the page or framework. The picker checks the page exists there
 * first (`whereIs`) and sends the reader home when it doesn't.
 */
export function frontendHref(
  path: string[],
  frontend: FrontendId,
  slug?: string,
) {
  // An early-access frontend's only page.
  const landing = landingPage(frontend);
  if (landing) return landing;
  const scope = scopeFromPath(path);
  const asked = slug ?? scope.slug;
  // Off React, the quickstart is the frontend's root page: `/mastra/quickstart`
  // on Vue is `/vue/mastra`, and on Slack the channel overview, `/slack/mastra`.
  const page = asked === "quickstart" && frontend !== "react" ? "" : asked;
  const fe = frontend !== "react" ? `/${frontendSegment(frontend)}` : "";
  const fw = scope.framework ? `/${scope.framework}` : "";
  const tail = page || (frontend === "react" ? "quickstart" : "");
  return `${fe}${fw}${tail ? `/${tail}` : ""}`;
}
